// ---- build objects with stable ids ----
function h(s){let x=2166136261;for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)}return (x>>>0).toString(36)}
const era=y=>y<2010?'00':y<2020?'10':'20';
window.HG={
  mc:MC.map(([g,y,c,d,q,a,w,n])=>({g,y,c,d,q,a,w,n,e:era(y),id:'m'+h(q)})),
  rel:TL.map(([g,y,d,t])=>({g,y,d,t,e:era(y),id:'t'+h(t)})),
  ori:COL.map(([g,y,d,a,c,x])=>({g,y,d,a,c,x:x||[],e:era(y),id:'c'+h(a)}))
};
